    public let projectPolicy: String?
    public let projectTrusted: Bool?
    public let routing: ConfigRoutingClass?
    public let rules: [RuleElement]
    public let sessionAllowed: [SessionAllowedElement]?
    public let sessionTitles: Bool
    public let trustedProjects: [String]

    public enum CodingKeys: String, CodingKey {
        case configFile = "config_file"
        case defaultModel = "default_model"
        case defaultPermissionMode = "default_permission_mode"
        case logLevel = "log_level"
        case notificationsOpenIn = "notifications_open_in"
        case permissionMode = "permission_mode"
        case projectPolicy = "project_policy"
        case projectTrusted = "project_trusted"
        case routing = "routing"
        case rules = "rules"
        case sessionAllowed = "session_allowed"
        case sessionTitles = "session_titles"
        case trustedProjects = "trusted_projects"
    }

    public init(configFile: String, defaultModel: String?, defaultPermissionMode: DefaultPermissionModeEnum?, logLevel: String, notificationsOpenIn: OpenIn?, permissionMode: DefaultPermissionModeEnum?, projectPolicy: String?, projectTrusted: Bool?, routing: ConfigRoutingClass?, rules: [RuleElement], sessionAllowed: [SessionAllowedElement]?, sessionTitles: Bool, trustedProjects: [String]) {
        self.configFile = configFile
        self.defaultModel = defaultModel
        self.defaultPermissionMode = defaultPermissionMode
        self.logLevel = logLevel
        self.notificationsOpenIn = notificationsOpenIn
        self.permissionMode = permissionMode
        self.projectPolicy = projectPolicy
        self.projectTrusted = projectTrusted
        self.routing = routing
