    public let error: ErrorClass
    public let id: ID?
    public let jsonrpc: Jsonrpc?

    public enum CodingKeys: String, CodingKey {
        case error = "error"
        case id = "id"
        case jsonrpc = "jsonrpc"
    }

    public init(error: ErrorClass, id: ID?, jsonrpc: Jsonrpc?) {
        self.error = error
        self.id = id
        self.jsonrpc = jsonrpc
    }
}

/// JSON-RPC error object.
// MARK: - ErrorClass
public struct ErrorClass: Codable {
    public let code: Int
    public let data: [String: JSONAny]?
    public let message: String

    public enum CodingKeys: String, CodingKey {
        case code = "code"
        case data = "data"
        case message = "message"
    }

    public init(code: Int, data: [String: JSONAny]?, message: String) {
        self.code = code
        self.data = data
        self.message = message
    }
}

public enum ID: Codable {
    case integer(Int)
    case string(String)
    case null

    public init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let x = try? container.decode(Int.self) {
            self = .integer(x)
            return
        }
        if let x = try? container.decode(String.self) {
            self = .string(x)
            return
        }
        if container.decodeNil() {
            self = .null
            return
        }
        throw DecodingError.typeMismatch(ID.self, DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Wrong type for ID"))
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .integer(let x):
            try container.encode(x)
        case .string(let x):
            try container.encode(x)
        case .null:
            try container.encodeNil()
        }
    }
}

