    public let planFirst: Bool?
    public let route: RouteEnum?
    public let sessionID: String
    public let status: SessionStatus
    public let step: String?
    public let title: String?
    public let trimmedAt: String?
    public let updatedAt: String
    public let waitLine: String?
    public let waitReason: Reason?

    public enum CodingKeys: String, CodingKey {
        case agent = "agent"
        case branch = "branch"
        case createdAt = "created_at"
        case cwd = "cwd"
        case forkedFrom = "forked_from"
        case helpersRunning = "helpers_running"
        case helpersWaiting = "helpers_waiting"
        case lastSeq = "last_seq"
        case localOnly = "local_only"
        case modelProfile = "model_profile"
        case origin = "origin"
        case parentSessionID = "parent_session_id"
        case pending = "pending"
        case pendingItems = "pending_items"
        case planFirst = "plan_first"
        case route = "route"
        case sessionID = "session_id"
        case status = "status"
        case step = "step"
        case title = "title"
        case trimmedAt = "trimmed_at"
        case updatedAt = "updated_at"
        case waitLine = "wait_line"
        case waitReason = "wait_reason"
    }

    public init(agent: String?, branch: String?, createdAt: String, cwd: String?, forkedFrom: String?, helpersRunning: Int?, helpersWaiting: Int?, lastSeq: Int, localOnly: Bool?, modelProfile: String, origin: String?, parentSessionID: String?, pending: SessionPendingItem?, pendingItems: [SessionPendingItem]?, planFirst: Bool?, route: RouteEnum?, sessionID: String, status: SessionStatus, step: String?, title: String?, trimmedAt: String?, updatedAt: String, waitLine: String?, waitReason: Reason?) {
        self.agent = agent
        self.branch = branch
        self.createdAt = createdAt
        self.cwd = cwd
        self.forkedFrom = forkedFrom
        self.helpersRunning = helpersRunning
        self.helpersWaiting = helpersWaiting
        self.lastSeq = lastSeq
        self.localOnly = localOnly
        self.modelProfile = modelProfile
        self.origin = origin
        self.parentSessionID = parentSessionID
        self.pending = pending
        self.pendingItems = pendingItems
        self.planFirst = planFirst
        self.route = route
        self.sessionID = sessionID
        self.status = status
        self.step = step
        self.title = title
        self.trimmedAt = trimmedAt
        self.updatedAt = updatedAt
        self.waitLine = waitLine
        self.waitReason = waitReason
    }
}

/// What a waiting session waits for, in a form a client can list without opening it.
///
/// ``kind`` is ``approval`` for a tool call that needs a yes, and ``consent`` for the paid
/// step-up question. ``since`` is the ``ts`` of the event that asked
/// (``approval.needed`` or ``route.consent.needed``). For an approval, ``call_id``,
/// ``name``,
/// ``subject`` and ``source`` are those of the ``approval.needed`` event, and ``added`` and
/// ``removed`` count the lines its diff adds and removes (null when the call has no diff).
/// For a consent, ``alternatives`` is the number of answers the user may give. A helper's
/// consent also carries ``helper_id``, ``agent``, ``label``, ``sent`` and ``not_sent`` of
/// its
